1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.index = index;
7	  }
8	}
9	PatchError.prototype.name = 'PatchError';
10	
11	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
12	const INDEX_RE = /^(0|[1-9][0-9]*)$/;
13	const BAD_ESCAPE_RE = /~(?![01])/;
14	
15	export function parsePointer(pointer) {
16	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
17	  if (pointer === '') return [];
18	  if (pointer[0] !== '/' || BAD_ESCAPE_RE.test(pointer)) throw new SyntaxError('invalid pointer');
19	  return pointer.slice(1).split('/').map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));
20	}
21	
22	function tryParsePointer(pointer) {
23	  if (typeof pointer !== 'string') return null;
24	  try {
25	    return parsePointer(pointer);
26	  } catch {
27	    return null;
28	  }
29	}
