31	function isObject(v) {
32	  return typeof v === 'object' && v !== null && !Array.isArray(v);
33	}
34	
35	// Sets an own data property; defineProperty keeps names such as `__proto__` ordinary.
36	function setMember(obj, name, value) {
37	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
38	}
39	
40	function clone(v) {
41	  if (Array.isArray(v)) return v.map(clone);
42	  if (isObject(v)) {
43	    const out = {};
44	    for (const k of Object.keys(v)) setMember(out, k, clone(v[k]));
45	    return out;
46	  }
47	  return v;
48	}
49	
50	function kind(v) {
51	  if (v === null) return 'null';
52	  if (Array.isArray(v)) return 'array';
53	  return typeof v;
54	}
55	
56	function equal(a, b) {
57	  const t = kind(a);
58	  if (t !== kind(b)) return false;
59	  if (t === 'array') return a.length === b.length && a.every((x, i) => equal(x, b[i]));
60	  if (t === 'object') {
61	    const keys = Object.keys(a);
62	    return keys.length === Object.keys(b).length
63	      && keys.every((k) => Object.hasOwn(b, k) && equal(a[k], b[k]));
64	  }
65	  return a === b;
66	}
67	
68	function fail(index, reason) {
69	  return new PatchError(`operation ${index}: ${reason}`, index);
70	}
71	
72	// Returns the value `token` names in `container`, or throws the matching failure.
73	function step(container, token, notFound, index) {
74	  if (Array.isArray(container)) {
75	    if (INDEX_RE.test(token)) {
76	      if (Number(token) < container.length) return container[Number(token)];
77	      throw fail(index, notFound);
78	    }
79	    throw fail(index, token === '-' ? notFound : 'bad index');
80	  }
81	  if (isObject(container) && Object.hasOwn(container, token)) return container[token];
82	  throw fail(index, notFound);
83	}
84	
85	function resolve(root, tokens, notFound, index) {
86	  let v = root;
87	  for (const token of tokens) v = step(v, token, notFound, index);
88	  return v;
89	}
90	
91	function addAt(root, tokens, value, index) {
92	  if (tokens.length === 0) return value;
93	  const parent = resolve(root, tokens.slice(0, -1), 'path not found', index);
94	  const last = tokens[tokens.length - 1];
95	  if (Array.isArray(parent)) {
96	    if (last === '-') {
97	      parent.push(value);
98	    } else if (INDEX_RE.test(last)) {
99	      if (Number(last) > parent.length) throw fail(index, 'path not found');
100	      parent.splice(Number(last), 0, value);
101	    } else {
102	      throw fail(index, 'bad index');
103	    }
104	  } else if (isObject(parent)) {
105	    setMember(parent, last, value);
106	  } else {
107	    throw fail(index, 'path not found');
108	  }
109	  return root;
110	}
111	
112	// Follows `tokens` (at least one) and returns the parent and last token of the named value.
113	function locate(root, tokens, notFound, index) {
114	  const parent = resolve(root, tokens.slice(0, -1), notFound, index);
115	  const last = tokens[tokens.length - 1];
116	  step(parent, last, notFound, index);
117	  return { parent, last };
118	}
119	
120	function removeAt(root, tokens, notFound, index) {
121	  const { parent, last } = locate(root, tokens, notFound, index);
122	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
123	  else delete parent[last];
124	}
125	
126	function sameTokens(a, b) {
127	  return a.length === b.length && a.every((t, i) => t === b[i]);
128	}
129	
130	function isProperPrefix(prefix, tokens) {
131	  return prefix.length < tokens.length && prefix.every((t, i) => t === tokens[i]);
132	}
133	
134	// Returns the form-rule reason the operation breaks, or a checked operation.
135	function checkForm(op) {
136	  if (typeof op !== 'object' || op === null || Array.isArray(op)) return { reason: 'not an object' };
137	  const name = Object.hasOwn(op, 'op') ? op.op : undefined;
138	  if (typeof name !== 'string' || !OPS.has(name)) return { reason: 'bad op' };
139	  const path = Object.hasOwn(op, 'path') ? tryParsePointer(op.path) : null;
140	  if (path === null) return { reason: 'bad path' };
141	  let from = null;
142	  if (name === 'move' || name === 'copy') {
143	    from = Object.hasOwn(op, 'from') ? tryParsePointer(op.from) : null;
144	    if (from === null) return { reason: 'bad from' };
145	  }
146	  const usesValue = name === 'add' || name === 'replace' || name === 'test';
147	  if (usesValue && !Object.hasOwn(op, 'value')) return { reason: 'missing value' };
148	  if (name === 'remove' && path.length === 0) return { reason: 'cannot remove root' };
149	  if (name === 'move' && isProperPrefix(from, path)) return { reason: 'cannot move into own child' };
150	  return { op: { name, path, from, value: usesValue ? op.value : undefined } };
151	}
152	
153	function applyOperation(root, { name, path, from, value }, index) {
154	  switch (name) {
155	    case 'add':
156	      return addAt(root, path, clone(value), index);
157	    case 'remove':
158	      removeAt(root, path, 'path not found', index);
159	      return root;
160	    case 'replace': {
161	      if (path.length === 0) return clone(value);
162	      const { parent, last } = locate(root, path, 'path not found', index);
163	      if (Array.isArray(parent)) parent[Number(last)] = clone(value);
164	      else setMember(parent, last, clone(value));
165	      return root;
166	    }
167	    case 'move': {
168	      const moved = resolve(root, from, 'from not found', index);
169	      if (sameTokens(from, path)) return root;
170	      removeAt(root, from, 'from not found', index);
171	      return addAt(root, path, moved, index);
172	    }
173	    case 'copy':
174	      return addAt(root, path, clone(resolve(root, from, 'from not found', index)), index);
175	    case 'test':
176	      if (!equal(resolve(root, path, 'path not found', index), value)) throw fail(index, 'test failed');
177	      return root;
178	    default:
179	      throw new Error(`unreachable op ${name}`);
180	  }
181	}
182	
183	export function applyPatch(doc, patch) {
184	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
185	  const ops = [];
186	  for (let i = 0; i < patch.length; i++) {
187	    const checked = checkForm(patch[i]);
188	    if (checked.reason) throw fail(i, checked.reason);
189	    ops.push(checked.op);
190	  }
191	  let root = clone(doc);
192	  ops.forEach((op, i) => {
193	    root = applyOperation(root, op, i);
194	  });
195	  return root;
196	}
