2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import fs from 'node:fs';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	
10	class CliError extends Error {
11	  constructor(message, exitCode) {
12	    super(message);
13	    this.exitCode = exitCode;
14	  }
15	}
16	
17	function readError(name, reason) {
18	  return new CliError(`Error: ${name}: ${reason}`, 1);
19	}
20	
21	function isDirectory(path) {
22	  try {
23	    return fs.statSync(path).isDirectory();
24	  } catch {
25	    return false;
26	  }
27	}
28	
29	function readFileLimited(path) {
30	  let fd;
31	  try {
32	    fd = fs.openSync(path, 'r');
33	  } catch (err) {
34	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(path, 'no such file');
35	    if (err.code === 'EISDIR' || isDirectory(path)) throw readError(path, 'is a directory');
36	    throw readError(path, 'cannot read');
37	  }
38	  try {
39	    if (fs.fstatSync(fd).isDirectory()) throw readError(path, 'is a directory');
40	    const chunks = [];
41	    let total = 0;
42	    for (;;) {
43	      const buf = Buffer.alloc(65536);
44	      const n = fs.readSync(fd, buf, 0, buf.length, null);
45	      if (n === 0) break;
46	      total += n;
47	      if (total > MAX_BYTES) throw readError(path, 'too large');
48	      chunks.push(buf.subarray(0, n));
49	    }
50	    return Buffer.concat(chunks);
51	  } catch (err) {
52	    if (err instanceof CliError) throw err;
53	    if (err.code === 'EISDIR') throw readError(path, 'is a directory');
54	    throw readError(path, 'cannot read');
55	  } finally {
56	    fs.closeSync(fd);
57	  }
58	}
59	
60	function readStdinLimited() {
61	  return new Promise((resolve, reject) => {
62	    const chunks = [];
63	    let total = 0;
64	    let stream;
65	    try {
66	      stream = process.stdin;
67	    } catch {
68	      reject(readError('stdin', 'cannot read'));
69	      return;
70	    }
71	    stream.on('data', (chunk) => {
72	      total += chunk.length;
73	      if (total > MAX_BYTES) {
74	        stream.destroy();
75	        reject(readError('stdin', 'too large'));
76	        return;
77	      }
78	      chunks.push(chunk);
79	    });
80	    stream.on('end', () => resolve(Buffer.concat(chunks)));
81	    stream.on('error', () => reject(readError('stdin', 'cannot read')));
82	  });
83	}
84	
85	function jsonDepth(value) {
86	  let max = 0;
87	  const stack = [[value, 0]];
88	  while (stack.length > 0) {
89	    const [v, depth] = stack.pop();
90	    if (typeof v !== 'object' || v === null) continue;
91	    const d = depth + 1;
92	    if (d > max) max = d;
93	    if (max > MAX_DEPTH) return max;
94	    for (const child of Object.values(v)) stack.push([child, d]);
95	  }
96	  return max;
97	}
98	
99	async function loadJson(arg) {
100	  const name = arg === '-' ? 'stdin' : arg;
101	  const bytes = arg === '-' ? await readStdinLimited() : readFileLimited(arg);
102	  let text;
103	  try {
104	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
105	  } catch {
106	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
107	  }
108	  let value;
109	  try {
110	    value = JSON.parse(text);
111	  } catch {
112	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
113	  }
114	  if (jsonDepth(value) > MAX_DEPTH) throw new CliError(`Error: ${name}: too deep`, 3);
115	  return value;
116	}
117	
118	async function main(args) {
119	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
120	  const [patchArg, docArg = '-'] = args;
121	  if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
122	  const patch = await loadJson(patchArg);
123	  const doc = await loadJson(docArg);
124	  let result;
125	  try {
126	    result = applyPatch(doc, patch);
127	  } catch (err) {
128	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
129	    throw err;
130	  }
131	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
132	}
133	
134	main(process.argv.slice(2)).catch((err) => {
135	  if (!(err instanceof CliError)) throw err;
136	  process.stderr.write(`${err.message}\n`);
137	  process.exitCode = err.exitCode;
138	});
